<script setup lang="ts">
import { ref, computed, onBeforeUnmount } from 'vue';
import type { CSSProperties } from 'vue';
import './styles/theme.css'; import './styles/slider.css';
type Value = number | [number, number];
const props = withDefaults(defineProps<{ modelValue?: Value; defaultValue?: Value; min?: number; max?: number; step?: number | null; range?: boolean; marks?: Record<number, string | { label: string; style?: CSSProperties }>; tooltip?: 'auto' | 'always' | 'none'; tooltipFormatter?: (value: number) => string; disabled?: boolean; vertical?: boolean; size?: 'sm' | 'md' | 'lg'; label?: string; showValue?: boolean; included?: boolean }>(), { min: 0, max: 100, step: 1, tooltip: 'auto', size: 'md', label: '数值', included: true });
const emit = defineEmits<{ 'update:modelValue': [value: Value]; change: [value: Value]; changeComplete: [value: Value] }>();
const inner = ref<Value>(props.defaultValue ?? (props.range ? [props.min, props.min] : props.min)); const current = computed(() => props.modelValue ?? inner.value); const values = computed(() => Array.isArray(current.value) ? [...current.value].sort((a, b) => a - b) : [current.value]); const points = computed(() => Object.keys(props.marks ?? {}).map(Number).filter(value => value >= props.min && value <= props.max).sort((a, b) => a - b)); const rail = ref<HTMLElement | null>(null); const dragging = ref<number | null>(null); const hovering = ref(false); let latest: Value = current.value;
const percent = (value: number) => ((value - props.min) / (props.max - props.min || 1)) * 100;
const lo = computed(() => props.range ? values.value[0] : props.included ? props.min : values.value[0]); const hi = computed(() => props.range ? values.value[1] : values.value[0]);
function snap(raw: number) { const value = Math.max(props.min, Math.min(props.max, raw)); if (props.step === null) return points.value.length ? points.value.reduce((closest, point) => Math.abs(point - value) < Math.abs(closest - value) ? point : closest) : value; const step = Math.max(Number.EPSILON, props.step); return Number(Math.max(props.min, Math.min(props.max, Math.round((value - props.min) / step) * step + props.min)).toFixed(String(step).split('.')[1]?.length ?? 0)); }
function update(index: number, value: number) { if (props.disabled) return; let next: Value = value; if (props.range) { const pair = [...values.value]; pair[index] = value; pair.sort((a, b) => a - b); next = [pair[0], pair[1]]; } latest = next; if (props.modelValue === undefined) inner.value = next; emit('update:modelValue', next); emit('change', next); }
let cleanup: (() => void) | undefined;
function start(event: PointerEvent, index?: number) { if (props.disabled || event.button !== 0 || !rail.value) return; event.preventDefault(); cleanup?.(); const rect = rail.value.getBoundingClientRect(); const point = (event: PointerEvent) => snap(props.min + (props.vertical ? 1 - (event.clientY - rect.top) / rect.height : (event.clientX - rect.left) / rect.width) * (props.max - props.min)); const value = point(event); const target = index ?? (props.range && Math.abs(value - values.value[1]) < Math.abs(value - values.value[0]) ? 1 : 0); dragging.value = target; if (index === undefined) update(target, value); rail.value.querySelectorAll<HTMLElement>('[role=slider]')[target]?.focus(); const move = (event: PointerEvent) => update(target, point(event)); const up = () => { cleanup?.(); dragging.value = null; emit('changeComplete', latest); }; cleanup = () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); window.removeEventListener('pointercancel', up); }; window.addEventListener('pointermove', move); window.addEventListener('pointerup', up); window.addEventListener('pointercancel', up); }
onBeforeUnmount(() => cleanup?.());
function key(event: KeyboardEvent, index: number) { if (props.disabled) return; const point = values.value[index]; const unit = props.step ?? 1; let next: number | undefined; const direction = ['ArrowRight', 'ArrowUp'].includes(event.key) ? 1 : -1; if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) { next = props.step === null && points.value.length ? points.value[Math.max(0, Math.min(points.value.length - 1, points.value.indexOf(point) + direction))] : snap(point + direction * unit); } if (event.key === 'Home') next = props.min; if (event.key === 'End') next = props.max; if (event.key === 'PageUp') next = snap(point + (props.max - props.min) / 10); if (event.key === 'PageDown') next = snap(point - (props.max - props.min) / 10); if (next !== undefined) { event.preventDefault(); update(index, next); emit('changeComplete', latest); } }
</script>
<template><div :class="['at-slider', `at-slider--${size}`, { 'at-slider--vertical': vertical, 'at-slider--disabled': disabled, 'at-slider--dragging': dragging !== null, 'at-slider--with-marks': points.length }]"><span v-if="showValue" class="at-slider__header"><span>{{ label }}</span><output>{{ values.join(' – ') }}</output></span><div class="at-slider__control" @mouseenter="hovering = true" @mouseleave="hovering = false"><div ref="rail" class="at-slider__rail" @pointerdown="start($event)"><div v-if="included" class="at-slider__track" :style="vertical ? { bottom: `${percent(lo)}%`, height: `${percent(hi) - percent(lo)}%` } : { left: `${percent(lo)}%`, width: `${percent(hi) - percent(lo)}%` }" /><span v-for="point in points" :key="point" :class="['at-slider__dot', { 'at-slider__dot--active': point >= lo && point <= hi && included }]" :style="vertical ? { bottom: `${percent(point)}%` } : { left: `${percent(point)}%` }" /><div v-for="(point, index) in values" :key="index" :class="['at-slider__handle', { 'at-slider__handle--active': dragging === index }]" :style="vertical ? { bottom: `${percent(point)}%` } : { left: `${percent(point)}%` }" role="slider" :tabindex="disabled ? -1 : 0" :aria-label="range ? `${label}${index === 0 ? '起始' : '结束'}` : label" :aria-valuemin="min" :aria-valuemax="max" :aria-valuenow="point" :aria-valuetext="tooltipFormatter?.(point)" :aria-orientation="vertical ? 'vertical' : 'horizontal'" :aria-disabled="disabled" @pointerdown.stop="start($event, index)" @keydown="key($event, index)"><span :class="['at-slider__tooltip', { 'at-slider__tooltip--visible': tooltip === 'always' || (tooltip === 'auto' && (hovering || dragging !== null)) }]">{{ tooltipFormatter?.(point) ?? point }}</span></div></div><div v-if="marks" class="at-slider__marks"><span v-for="point in points" :key="point" class="at-slider__mark" :style="[vertical ? { bottom: `${percent(point)}%` } : { left: `${percent(point)}%` }, typeof marks[point] === 'object' ? marks[point].style : undefined]" @click="update(0, point); emit('changeComplete', latest)">{{ typeof marks[point] === 'object' ? marks[point].label : marks[point] }}</span></div></div></div></template>
